class Solution {
  public String lastSubstring(String s) {
    int i = 0, j = 1, k = 0, n = s.length();
    while (j + k < n) {
      char a = s.charAt(i + k), b = s.charAt(j + k);
      if (a == b) {
        k++;
        continue;
      }
      if (a < b) i = i + k + 1;
      else j = j + k + 1;
      if (i == j) j++;
      k = 0;
    }
    return s.substring(i);
  }
}
